{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    min_sum = sum(s['minimum'] for s in segments)
    max_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > max_sum:
        raise ValueError('Budget out of feasible range')
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                score = seg['importance'] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            # Should not happen because we have budget <= max_sum
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"
}
